import{_ as o,W as i,s as d,u,I as n,ah as p,w as t,Z as l,A as e}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const x=JSON.parse('{"title":"搭建私有云：OwnCloud | LCTT x X-CMD","titleTemplate":false,"description":"搭建私有云：OwnCloud | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"搭建私有云：OwnCloud | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"搭建私有云：OwnCloud | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180129 Create your own personal Cloud- Install OwnCloud","title":"搭建私有云：OwnCloud","tag":"201803"},"relativePath":"201803/20180129 Create your own personal Cloud- Install OwnCloud.md","filePath":"[post].md"}'),r={name:"201803/20180129 Create your own personal Cloud- Install OwnCloud.md"};function c(h,s,g,m,C,b){const a=i("Link");return u(),d("div",null,[s[23]||(s[23]=n("h1",{id:"搭建私有云-owncloud",tabindex:"-1"},[t("搭建私有云：OwnCloud "),n("a",{class:"header-anchor",href:"#搭建私有云-owncloud","aria-label":"Permalink to 搭建私有云：OwnCloud"},"​")],-1)),s[24]||(s[24]=n("p",null,"所有人都在讨论云。尽管市面上有很多为我们提供云存储和其他云服务的主要服务商，但是我们还是可以为自己搭建一个私有云。",-1)),s[25]||(s[25]=n("p",null,"在本教程中，我们将讨论如何利用 OwnCloud 搭建私有云。OwnCloud 是一个可以安装在我们 Linux 设备上的 web 应用程序，能够存储和用我们的数据提供服务。OwnCloud 可以分享日历、联系人和书签，共享音/视频流等等。",-1)),s[26]||(s[26]=n("p",null,"本教程中，我们使用的是 CentOS 7 系统，但是本教程同样适用于其他 Linux 发行版中安装 OwnCloud。让我们开始安装 OwnCloud 并且做一些准备工作，",-1)),n("ul",null,[n("li",null,[s[1]||(s[1]=t("推荐阅读：")),l(a,{href:"http://linuxtechlab.com/apache-as-reverse-proxy-centos-rhel/"},{default:e(()=>s[0]||(s[0]=[t("如何在 CentOS & RHEL 上使用 Apache 作为反向代理服务器")])),_:1})]),n("li",null,[s[3]||(s[3]=t("同时推荐：")),l(a,{href:"http://linuxtechlab.com/linux-server-glances-monitoring-tool/"},{default:e(()=>s[2]||(s[2]=[t("实时 Linux 服务器监测和 GLANCES 监测工具")])),_:1})])]),s[27]||(s[27]=n("h3",{id:"预备",tabindex:"-1"},[t("预备 "),n("a",{class:"header-anchor",href:"#预备","aria-label":"Permalink to 预备"},"​")],-1)),n("ul",null,[n("li",null,[s[6]||(s[6]=t("我们需要在机器上配置 LAMP。参照阅读我们的文章《")),l(a,{href:"http://linuxtechlab.com/easiest-guide-creating-lamp-server/"},{default:e(()=>s[4]||(s[4]=[t("在 CentOS/RHEL 上配置 LAMP 服务器最简单的教程")])),_:1}),s[7]||(s[7]=t("》 & 《")),l(a,{href:"http://linuxtechlab.com/install-lamp-stack-on-ubuntu/"},{default:e(()=>s[5]||(s[5]=[t("在 Ubuntu 搭建 LAMP")])),_:1}),s[8]||(s[8]=t("》。"))]),s[9]||(s[9]=p("<li>我们需要在自己的设备里安装这些包，<code>php-mysql</code>、 <code>php-json</code>、 <code>php-xml</code>、 <code>php-mbstring</code>、 <code>php-zip</code>、 <code>php-gd</code>、 <code>curl、 </code>php-curl<code> 、</code>php-pdo`。使用包管理器安装它们。</li>",1))]),s[28]||(s[28]=p(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo yum install php-mysql php-json php-xml php-mbstring php-zip php-gd curl php-curl php-pdo</span></span></code></pre></div><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to 安装">​</a></h3><p>安装 OwnCloud，我们现在需要在服务器上下载 OwnCloud 安装包。使用下面的命令从官方网站下载最新的安装包（10.0.4-1）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://download.owncloud.org/community/owncloud-10.0.4.tar.bz2</span></span></code></pre></div><p>使用下面的命令解压：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tar -xvf owncloud-10.0.4.tar.bz2</span></span></code></pre></div><p>现在，将所有解压后的文件移动至 <code>/var/www/html</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mv owncloud/* /var/www/html</span></span></code></pre></div><p>下一步，我们需要在 Apache 的配置文件 <code>httpd.conf</code> 上做些修改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo vim /etc/httpd/conf/httpd.conf</span></span></code></pre></div><p>更改下面的选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AllowOverride All</span></span></code></pre></div><p>保存该文件，并修改 OwnCloud 文件夹的文件权限：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo chown -R apache:apache /var/www/html/</span></span>
<span class="line"><span>$ sudo chmod 777 /var/www/html/config/</span></span></code></pre></div><p>然后重启 Apache 服务器执行修改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl restart httpd</span></span></code></pre></div><p>现在，我们需要在 MariaDB 上创建一个数据库，保存来自 OwnCloud 的数据。使用下面的命令创建数据库和数据库用户：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>MariaDB [(none)] &gt; create database owncloud;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; GRANT ALL ON owncloud.* TO ocuser@localhost IDENTIFIED BY &#39;owncloud&#39;;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; flush privileges;</span></span>
<span class="line"><span>MariaDB [(none)] &gt; exit</span></span></code></pre></div><p>服务器配置部分完成后，现在我们可以在网页浏览器上访问 OwnCloud。打开浏览器，输入您的服务器 IP 地址，我这边的服务器是 10.20.30.100：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud1-compressor.jpg?resize=400%2C647" alt="安装 owncloud"></p><p>一旦 URL 加载完毕，我们将呈现上述页面。这里，我们将创建管理员用户同时提供数据库信息。当所有信息提供完毕，点击“Finish setup”。</p><p>我们将被重定向到登录页面，在这里，我们需要输入先前创建的凭据：</p><p><img src="https://i1.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud2-compressor1.jpg?resize=876%2C541" alt="安装 owncloud"></p><p>认证成功之后，我们将进入 OwnCloud 面板：</p><p><img src="https://i0.wp.com/linuxtechlab.com/wp-content/uploads/2018/01/owncloud3-compressor1.jpg?resize=981%2C474" alt="安装 owncloud"></p><p>我们可以使用手机应用程序，同样也可以使用网页界面更新我们的数据。现在，我们已经有自己的私有云了，同时，关于如何安装 OwnCloud 创建私有云的教程也进入尾声。请在评论区留下自己的问题或建议。</p><hr>`,27)),n("p",null,[s[11]||(s[11]=t("via: ")),l(a,{href:"http://linuxtechlab.com/create-personal-cloud-install-owncloud/"},{default:e(()=>s[10]||(s[10]=[t("http://linuxtechlab.com/create-personal-cloud-install-owncloud/")])),_:1})]),n("p",null,[s[15]||(s[15]=t("作者：")),l(a,{href:"http://linuxtechlab.com/author/shsuain/"},{default:e(()=>s[12]||(s[12]=[t("SHUSAIN")])),_:1}),s[16]||(s[16]=t(" 译者：")),l(a,{href:"https://github.com/CYLeft"},{default:e(()=>s[13]||(s[13]=[t("CYLeft")])),_:1}),s[17]||(s[17]=t(" 校对：")),l(a,{href:"https://github.com/wxy"},{default:e(()=>s[14]||(s[14]=[t("wxy")])),_:1})]),n("p",null,[s[20]||(s[20]=t("本文由 ")),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>s[18]||(s[18]=[t("LCTT")])),_:1}),s[21]||(s[21]=t(" 原创编译，")),l(a,{href:"https://linux.cn/"},{default:e(()=>s[19]||(s[19]=[t("Linux中国")])),_:1}),s[22]||(s[22]=t(" 荣誉推出"))])])}const f=o(r,[["render",c]]);export{x as __pageData,f as default};
